import numpy as np
from scipy.optimize import minimize

def objective(vars):
    a, b, c = vars
    return -(a**2 + a + b**2 + b + c**2 + c)

def constraint(vars):
    a, b, c = vars
    return a**3 + b**3 + c**3 - 1

cons = ({'type': 'eq', 'fun': constraint})
bounds = [(-1, 2), (-1, 2), (-1, 2)]

best_f = -float('inf')
# Check a grid of points and then optimize from each
for a_start in np.linspace(-1, 2, 10):
    for b_start in np.linspace(-1, 2, 10):
        c_start = (1 - a_start**3 - b_start**3)**(1/3)
        if c_start < -1:
            continue
        if c_start > 2:
            continue
        res = minimize(objective, [a_start, b_start, c_start], method='SLSQP', bounds=bounds, constraints=cons)
        if res.success:
            f = -res.fun
            if f > best_f:
                best_f = f
                best_vars = res.x

print(f"Best f: {best_f} at {best_vars}")
